import{_ as e,o,c as d,a5 as r}from"./chunks/framework.BEZBAInb.js";const u=JSON.parse('{"title":"Introduction","description":"","frontmatter":{"title":"Introduction","order":1},"headers":[],"relativePath":"en/latest/web-tool/guide.md","filePath":"en/latest/web-tool/guide.md","lastUpdated":1788455378000}'),a={name:"en/latest/web-tool/guide.md"};function l(i,t,n,s,h,c){return o(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="konado-webtool" tabindex="-1">Konado WebTool <a class="header-anchor" href="#konado-webtool" aria-label="Permalink to &quot;Konado WebTool&quot;">​</a></h1><h2 id="preface" tabindex="-1">Preface <a class="header-anchor" href="#preface" aria-label="Permalink to &quot;Preface&quot;">​</a></h2><p>Konado WebTool is a plugin that provides Web platform development tool support for Konado projects. Because Godot 4.x captures and disables all keyboard shortcuts by default on the Web platform, browser developer tool shortcuts such as F12 and F5 cannot be used normally. This plugin solves that problem by allowing common browser developer tool shortcuts on the Web platform, making it easier for developers to debug and develop in Web environments.</p><h2 id="how-it-works" tabindex="-1">How It Works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How It Works&quot;">​</a></h2><p>Konado WebTool works by injecting JavaScript code on the Web platform to let shortcuts pass through. It will:</p><ol><li>Detect whether the current platform is Web</li><li>If it is Web and developer tool support is enabled, inject shortcut handling code</li><li>Dynamically build the allowed shortcut list based on configuration</li><li>Stop allowed shortcuts from propagating to Godot while preserving the browser&#39;s default behavior</li></ol><h3 id="comparison-with-other-solutions" tabindex="-1">Comparison with Other Solutions <a class="header-anchor" href="#comparison-with-other-solutions" aria-label="Permalink to &quot;Comparison with Other Solutions&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Solution</th><th>Advantages</th><th>Disadvantages</th></tr></thead><tbody><tr><td>Konado WebTool</td><td>Easy to use, highly configurable, easy to maintain</td><td>No obvious disadvantages</td></tr><tr><td>Manually modify export template</td><td>Full control</td><td>High technical requirements, frequent updates needed</td></tr><tr><td>Switch development environment</td><td>Can debug on desktop platform</td><td>Cannot catch Web-platform-specific issues</td></tr></tbody></table><h2 id="supported-browser-shortcuts" tabindex="-1">Supported Browser Shortcuts <a class="header-anchor" href="#supported-browser-shortcuts" aria-label="Permalink to &quot;Supported Browser Shortcuts&quot;">​</a></h2><p>These shortcut specifications are based on standard developer tool shortcuts in mainstream browsers such as Chrome, Firefox, and Edge, and refer to official browser documentation:</p><ul><li><a href="https://developer.mozilla.org/en-US/docs/Tools/Keyboard_shortcuts" target="_blank" rel="noreferrer">Firefox DevTools</a></li><li><a href="https://learn.microsoft.com/en-us/microsoft-edge/devtools-guide-chromium/shortcuts/" target="_blank" rel="noreferrer">Edge DevTools</a></li><li><a href="https://developer.chrome.com/docs/devtools/shortcuts/" target="_blank" rel="noreferrer">Chrome DevTools</a></li><li><a href="https://webkit.org/web-inspector/keyboard-shortcuts/" target="_blank" rel="noreferrer">Safari DevTools (WebKit)</a></li></ul><table tabindex="0"><thead><tr><th>Shortcut</th><th>Function</th><th>Enable option</th></tr></thead><tbody><tr><td>F12</td><td>Open developer tools</td><td><code>enable_f12</code></td></tr><tr><td>F5</td><td>Refresh page</td><td><code>enable_f5</code></td></tr><tr><td>F11</td><td>Toggle full screen</td><td><code>enable_f11</code></td></tr><tr><td>Ctrl+Shift+I (Win/Linux) / Cmd+Opt+I (Mac)</td><td>Open Elements panel</td><td><code>enable_ctrl_shift_i</code></td></tr><tr><td>Ctrl+Shift+J (Win/Linux) / Cmd+Opt+J (Mac)</td><td>Open Console</td><td><code>enable_ctrl_shift_j</code></td></tr><tr><td>Ctrl+Shift+C (Win/Linux) / Cmd+Shift+C (Mac)</td><td>Inspect element mode</td><td><code>enable_ctrl_shift_c</code></td></tr><tr><td>Ctrl+U (Win/Linux) / Cmd+U (Mac)</td><td>View page source</td><td><code>enable_ctrl_u</code></td></tr><tr><td>Ctrl+R (Win/Linux) / Cmd+R (Mac)</td><td>Refresh page</td><td><code>enable_ctrl_r</code></td></tr></tbody></table><h2 id="configuration-options" tabindex="-1">Configuration Options <a class="header-anchor" href="#configuration-options" aria-label="Permalink to &quot;Configuration Options&quot;">​</a></h2><p>In the autoloaded <code>KonadoWebTool</code> node, you can configure the following properties:</p><table tabindex="0"><thead><tr><th>Property</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>developer_shortcuts_enabled</code></td><td>bool</td><td>true</td><td>Whether to allow Web developer tool shortcuts</td></tr><tr><td><code>allow_in_release</code></td><td>bool</td><td>false</td><td>Whether to allow shortcuts in release exports</td></tr><tr><td><code>enable_f12</code></td><td>bool</td><td>true</td><td>Whether to enable F12</td></tr><tr><td><code>enable_f5</code></td><td>bool</td><td>true</td><td>Whether to enable F5</td></tr><tr><td><code>enable_f11</code></td><td>bool</td><td>true</td><td>Whether to enable F11</td></tr><tr><td><code>enable_ctrl_shift_i</code></td><td>bool</td><td>true</td><td>Whether to enable Ctrl+Shift+I</td></tr><tr><td><code>enable_ctrl_shift_j</code></td><td>bool</td><td>true</td><td>Whether to enable Ctrl+Shift+J</td></tr><tr><td><code>enable_ctrl_shift_c</code></td><td>bool</td><td>true</td><td>Whether to enable Ctrl+Shift+C</td></tr><tr><td><code>enable_ctrl_u</code></td><td>bool</td><td>true</td><td>Whether to enable Ctrl+U</td></tr><tr><td><code>enable_ctrl_r</code></td><td>bool</td><td>true</td><td>Whether to enable Ctrl+R</td></tr></tbody></table><p>To avoid exposing debugging entry points in production, release exports do not install the shortcut handler by default. After changing these properties at runtime, apply the configuration with:</p><div class="language-gdscript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">gdscript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">KonadoWebTool</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">refresh_shortcuts</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span></span></code></pre></div>',17)])])}const b=e(a,[["render",l]]);export{u as __pageData,b as default};
